package com.quicktest.modules.assessment.ai.dto;

import com.quicktest.modules.assessment.entity.QuestionType;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.ArrayList;
import java.util.List;

/**
 * Question DTO generated by AI representing a candidate question in staging/preview.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class AiGeneratedQuestionDto {

    private String tempId;
    private String content;
    private QuestionType questionType;
    @Builder.Default
    private Double points = 1.0;
    private String explanation;
    private String difficulty; // EASY, MEDIUM, HARD
    private String sampleAnswer;
    private String gradingRubric;
    private Double numericTolerance;

    @Builder.Default
    private List<AiGeneratedOptionDto> options = new ArrayList<>();
}
